import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.QueryValueEvaluationStep;
import org.eclipse.rdf4j.query.algebra.evaluation.impl.QueryEvaluationContext;
import org.eclipse.rdf4j.sail.lmdb.ValueStore;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Gap-analysis G7: an OPTIONAL with a condition must not lose the left-join acceleration tiers. The tiers (per-key
 * memo, replay, payload hash, estimate-triggered sweep) all gate on {@code memoReadMask(right)}, and a
 * {@code FilterPlan} carrying {@code filterMask = -1} poisons that mask — so a filtered OPTIONAL degraded to a per-row
 * nested loop even when the condition is a plain placeable comparison. The planner must thread
 * {@code placeableFilterMask(condition)} through the filter seam, exactly as the null-rejecting rewrite in
 * {@code LmdbNativeAggregateFilterCompiler} already does for its inner-join form.
 */
class LmdbNativeFilteredOptionalAccelerationTest {

	private static final String EX = "http://example.com/";

	private LmdbNativeAggregatePlanner compiler;

	@BeforeEach
	void setUp() {
		QueryEvaluationContext context = mock(QueryEvaluationContext.class);
		LmdbNativeEvaluationStrategy strategy = mock(LmdbNativeEvaluationStrategy.class);
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class);
		LmdbNativeValueCodec codec = new LmdbNativeValueCodec(mock(ValueStore.class));
		QueryValueEvaluationStep generic = bindings -> SimpleValueFactory.getInstance().createLiteral(false);

		when(strategy.getQueryEvaluationMode()).thenReturn(QueryEvaluationMode.STRICT);
		when(strategy.precompile(any(ValueExpr.class), any(QueryEvaluationContext.class))).thenReturn(generic);
		when(source.nativeValueCodec()).thenReturn(codec);
		Map<Value, Long> ids = new HashMap<>();
		AtomicLong nextId = new AtomicLong(1000L);
		when(source.idOf(any(Value.class)))
				.thenAnswer(invocation -> ids.computeIfAbsent(invocation.getArgument(0),
						ignored -> nextId.getAndIncrement()));
		when(source.exactDegree(anyLong(), anyLong(), anyBoolean())).thenReturn(OptionalLong.empty());

		compiler = new LmdbNativeAggregatePlanner(context, strategy, source);
	}

	/**
	 * A multi-pattern OPTIONAL arm under a placeable comparison: the compiled right side's memo mask must stay
	 * non-negative so the per-key memo/replay/sweep tiers can engage. With the mask poisoned every probe re-runs the
	 * whole arm per left row.
	 */
	@Test
	void placeableOptionalConditionKeepsMultiPatternRightArmMemoizable() {
		LeftJoin leftJoin = new LeftJoin(pattern("s", "a", "l"),
				new Join(pattern("s", "b", "o"), pattern("o", "c", "x")));
		leftJoin.setCondition(greaterThanFive("o"));

		SlotPlan plan = compiler.compileTuple(leftJoin, false);

		assertThat(plan).isInstanceOf(LeftJoinPlan.class);
		assertThat(LmdbNativeAggregateCompiler.memoReadMask(((LeftJoinPlan) plan).right))
				.as("a placeable OPTIONAL condition must not poison the right arm's memo mask — every left-join "
						+ "acceleration tier gates on it")
				.isGreaterThanOrEqualTo(0L);
	}

	/** The single-pattern arm: the payload/membership probes gate on the same mask discipline. */
	@Test
	void placeableOptionalConditionKeepsSinglePatternRightArmMemoizable() {
		LeftJoin leftJoin = new LeftJoin(pattern("s", "a", "l"), pattern("s", "b", "o"));
		leftJoin.setCondition(greaterThanFive("o"));

		SlotPlan plan = compiler.compileTuple(leftJoin, false);

		assertThat(plan).isInstanceOf(LeftJoinPlan.class);
		assertThat(LmdbNativeAggregateCompiler.memoReadMask(((LeftJoinPlan) plan).right))
				.as("a placeable OPTIONAL condition over a single-pattern arm must keep the arm's reads declared")
				.isGreaterThanOrEqualTo(0L);
	}

	/**
	 * The conservative fallback is preserved: a non-repeatable condition (RAND) is not placeable, so the filter must
	 * keep {@code filterMask = -1} and stay exactly where the algebra put it.
	 */
	@Test
	void nonRepeatableOptionalConditionStaysPinnedWithPoisonedMask() {
		LeftJoin leftJoin = new LeftJoin(pattern("s", "a", "l"), pattern("s", "b", "o"));
		leftJoin.setCondition(new Compare(new FunctionCall("RAND", new ValueExpr[0]),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral(0.5)), Compare.CompareOp.LT));

		SlotPlan plan = compiler.compileTuple(leftJoin, false);

		if (plan == null) {
			// the compiler may decline non-repeatable conditions outright; that is an equally conservative outcome
			return;
		}
		assertThat(plan).isInstanceOf(LeftJoinPlan.class);
		assertThat(LmdbNativeAggregateCompiler.memoReadMask(((LeftJoinPlan) plan).right))
				.as("a non-repeatable OPTIONAL condition must keep the right arm unmemoizable")
				.isEqualTo(-1L);
	}

	private static StatementPattern pattern(String subjectVar, String predicateLocalName, String objectVar) {
		return new StatementPattern(new Var(subjectVar),
				constant(SimpleValueFactory.getInstance().createIRI(EX, predicateLocalName)), new Var(objectVar));
	}

	private static ValueExpr greaterThanFive(String name) {
		return new Compare(new Var(name), new ValueConstant(SimpleValueFactory.getInstance().createLiteral(5)),
				Compare.CompareOp.GT);
	}

	private static Var constant(Value value) {
		return new Var("_const_" + value.stringValue(), value, true, true);
	}
}
